cypress_script:
describe('Notification Messages', () => {
  it('should display a notification message when clicking the link', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('a').contains('Click here').click();
    cy.url().should('include', '/notification_message_rendered');
    cy.get('#flash-messages').should('be.visible');
  });

  it('should not change the URL when the page is visited directly', () => {
    cy.visit('https://the-internet.herokuapp.com/notification_message_rendered');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/notification_message_rendered');
    cy.get('#flash-messages').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Notification Messages', () => {
  test('should display a notification message when clicking the link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await page.click('a:has-text("Click here")');
    await expect(page).toHaveURL(/notification_message_rendered/);
    await expect(page.locator('#flash-messages')).toBeVisible();
  });

  test('should not change the URL when the page is visited directly', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/notification_message_rendered');
    await expect(page.locator('#flash-messages')).not.toBeVisible();
  });
});
